  const workspace = [
    { to: '/settings', label: t('crm.account.nav.company'), app: true },
    { to: '/settings/api', label: t('crm.account.nav.api'), app: true },
    { to: '/billing', label: t('crm.account.nav.billing'), app: true },
    { to: '/staff', label: t('crm.account.nav.staff'), app: true },
    ...(isOwnerLike
      ? [{ to: '/staff/permissions', label: t('crm.account.nav.permissions'), app: true }]
