        <div className="flex flex-col lg:flex-row gap-6 items-start">
          <aside className="w-full lg:w-60 shrink-0 space-y-6">
            <div>
              <div className="text-[10px] font-semibold uppercase tracking-[0.18em] text-slate-500 mb-2 px-1">
                {t('crm.account.nav.groupAccount')}
              </div>
              <nav className="space-y-1 rounded-2xl border border-slate-800/90 bg-slate-950/70 p-2 shadow-[0_20px_50px_rgba(0,0,0,0.35)]">
                {main.map((item) => (
                  <NavLink
                    key={item.to}
                    to={item.to}
                    end={item.end}
