                {workspace.map((item) => {
                  const href = item.app ? `/app${item.to}` : item.to;
                  const active =
                    location.pathname === item.to ||
                    location.pathname === `/app${item.to}` ||
                    location.pathname.startsWith(`${item.to}/`) ||
                    location.pathname.startsWith(`/app${item.to}/`);
                  return (
                    <a
                      key={item.to}
                      href={href}
                      className={navClass(active)}
