          <section className="flex-1 min-w-0 w-full rounded-2xl border border-slate-800/90 bg-slate-950/40 p-5 md:p-8 shadow-[0_24px_60px_rgba(0,0,0,0.25)]">
            <Outlet />
          </section>
        </div>
      </div>
    </MainLayout>
  );
};

