import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { fetchMe, type MeDto } from '../../../api/users';
import { getStoredTenantName } from '../../../auth/session';
import { resolvePublicAssetUrl } from '../../../api/client';

function formatDate(iso: string | null | undefined, locale: string) {
  if (!iso) return '—';
  try {
    return new Date(iso).toLocaleString(locale);
  } catch {
    return iso;
  }
}

export const AccountOverviewTab: React.FC = () => {
  const { t, i18n } = useTranslation();
  const locale =
    i18n.language?.startsWith('tr') ? 'tr-TR' : i18n.language?.startsWith('en') ? 'en-US' : 'ru-RU';
  const [me, setMe] = useState<MeDto | null>(null);
  const [err, setErr] = useState<string | null>(null);

  useEffect(() => {
    let alive = true;
    fetchMe()
      .then((u) => {
        if (alive) setMe(u);
      })
      .catch((e) => {
        if (alive) setErr(e?.message || t('crm.account.personal.errors.load'));
      });
    return () => {
      alive = false;
    };
  }, [t]);

  const tenantName = getStoredTenantName();
  const role = (me?.role || '').toLowerCase();
  const roleBadge =
    role === 'owner'
      ? t('crm.account.badges.owner')
      : role === 'admin'
        ? t('crm.account.badges.admin')
        : me?.role || '—';
  const status = (me?.status || 'active').toLowerCase();
  const statusLabel =
    status === 'disabled'
      ? t('crm.account.badges.disabled')
      : t('crm.account.badges.active');

  const avatarSrc = resolvePublicAssetUrl(me?.avatarUrl || null);

  return (
    <div className="space-y-6">
      <p className="text-sm text-slate-400 leading-relaxed">{t('crm.account.overview.hint')}</p>

      {err && (
        <div className="text-xs text-red-300 bg-red-950/40 border border-red-800/50 rounded-xl px-3 py-2">
          {err}
        </div>
      )}

      <div className="grid gap-4 md:grid-cols-2">
        <div className="rounded-2xl border border-slate-800/80 bg-slate-900/50 p-5">
          <div className="text-[11px] font-semibold uppercase tracking-[0.16em] text-slate-500">
            {t('crm.account.overview.cardIdentity')}
          </div>
          <div className="mt-4 flex items-start gap-4">
            <div className="h-16 w-16 shrink-0 overflow-hidden rounded-2xl border border-slate-700 bg-slate-800">
              {avatarSrc ? (
                <img src={avatarSrc} alt="" className="h-full w-full object-cover" />
              ) : (
                <div className="flex h-full w-full items-center justify-center text-lg font-semibold text-slate-300">
                  {(me?.name?.[0] || me?.email?.[0] || '?').toUpperCase()}
                </div>
              )}
            </div>
            <div className="min-w-0">
              <div className="text-lg font-semibold text-slate-50 truncate">
                {me?.name || me?.email || '—'}
              </div>
              <div className="text-sm text-slate-400 truncate">{me?.email}</div>
              <div className="mt-3 flex flex-wrap gap-2">
                <span className="rounded-full border border-slate-700 bg-slate-800/80 px-2.5 py-0.5 text-[11px] text-slate-200">
                  {roleBadge}
                </span>
                <span className="rounded-full border border-slate-700 bg-slate-800/80 px-2.5 py-0.5 text-[11px] text-slate-200">
                  {statusLabel}
                </span>
              </div>
            </div>
          </div>
        </div>

        <div className="rounded-2xl border border-slate-800/80 bg-slate-900/50 p-5">
          <div className="text-[11px] font-semibold uppercase tracking-[0.16em] text-slate-500">
            {t('crm.account.overview.cardTenant')}
          </div>
          <div className="mt-4 space-y-3 text-sm">
            <div>
              <div className="text-[11px] text-slate-500">{t('crm.nav.settingsCompany')}</div>
              <div className="mt-0.5 font-medium text-slate-100">
                {tenantName?.trim() || t('crm.account.overview.tenantNameFallback')}
              </div>
            </div>
            <div>
              <div className="text-[11px] text-slate-500">{t('crm.account.overview.tenantId')}</div>
              <div className="mt-0.5 font-mono text-xs text-slate-300 break-all">{me?.tenantId || '—'}</div>
            </div>
            <div className="grid grid-cols-2 gap-3 pt-1">
              <div>
                <div className="text-[11px] text-slate-500">{t('crm.account.overview.memberSince')}</div>
                <div className="mt-0.5 text-slate-200">{formatDate(me?.createdAt, locale)}</div>
              </div>
              <div>
                <div className="text-[11px] text-slate-500">{t('crm.account.overview.lastActive')}</div>
                <div className="mt-0.5 text-slate-200">
                  {me?.lastActiveAt ? formatDate(me.lastActiveAt, locale) : t('crm.account.overview.never')}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div>
        <div className="text-sm font-semibold text-slate-100">{t('crm.account.overview.quickLinks')}</div>
        <p className="mt-1 text-xs text-slate-500">{t('crm.account.overview.quickLinksHint')}</p>
        <div className="mt-4 flex flex-wrap gap-2">
          <Link
            to="/app/profile/personal"
            className="rounded-xl border border-slate-700 bg-slate-800/50 px-3 py-2 text-xs font-medium text-slate-200 hover:border-violet-500/40 hover:bg-violet-950/30"
          >
            {t('crm.account.nav.personal')} →
          </Link>
          <Link
            to="/app/profile/security"
            className="rounded-xl border border-slate-700 bg-slate-800/50 px-3 py-2 text-xs font-medium text-slate-200 hover:border-violet-500/40 hover:bg-violet-950/30"
          >
            {t('crm.account.nav.security')} →
          </Link>
          <Link
            to="/app/settings"
            className="rounded-xl border border-slate-700 bg-slate-800/50 px-3 py-2 text-xs font-medium text-slate-200 hover:border-violet-500/40 hover:bg-violet-950/30"
          >
            {t('crm.account.nav.company')} →
          </Link>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { changeMyPassword } from '../../../api/users';

export const AccountSecurityTab: React.FC = () => {
  const { t } = useTranslation();
  const [oldPassword, setOldPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [newPassword2, setNewPassword2] = useState('');
  const [passSaving, setPassSaving] = useState(false);
  const [passError, setPassError] = useState<string | null>(null);
  const [passSuccess, setPassSuccess] = useState<string | null>(null);

  const handleChangePassword = async () => {
    setPassError(null);
    setPassSuccess(null);
    if (!oldPassword || !newPassword) {
      setPassError(t('crm.account.security.errors.required'));
      return;
    }
    if (newPassword !== newPassword2) {
      setPassError(t('crm.account.security.errors.mismatch'));
      return;
    }
    setPassSaving(true);
    try {
      await changeMyPassword(oldPassword, newPassword);
      setPassSuccess(t('crm.account.security.success'));
      setOldPassword('');
      setNewPassword('');
      setNewPassword2('');
    } catch (e: any) {
      setPassError(e.message || t('crm.account.security.errors.failed'));
    } finally {
      setPassSaving(false);
    }
  };

  return (
    <div className="max-w-xl space-y-6">
      <div>
        <h2 className="text-lg font-semibold text-slate-50">{t('crm.account.security.title')}</h2>
        <p className="mt-1 text-sm text-slate-400">{t('crm.account.security.subtitle')}</p>
      </div>

      {passError && (
        <div className="text-xs text-red-300 bg-red-950/40 border border-red-800/50 rounded-xl px-3 py-2">
          {passError}
        </div>
      )}
      {passSuccess && (
        <div className="text-xs text-emerald-300 bg-emerald-900/30 border border-emerald-700/60 rounded-xl px-3 py-2">
          {passSuccess}
        </div>
      )}

      <div className="space-y-4">
        <div>
          <label className="text-[11px] text-slate-500">{t('crm.account.security.current')}</label>
          <input
            type="password"
            value={oldPassword}
            onChange={(e) => setOldPassword(e.target.value)}
            autoComplete="current-password"
            className="mt-1 w-full rounded-xl border border-slate-800 bg-slate-950/80 px-3 py-2.5 text-sm text-slate-100 outline-none focus:border-violet-500/50"
          />
        </div>
        <div>
          <label className="text-[11px] text-slate-500">{t('crm.account.security.new')}</label>
          <input
            type="password"
            value={newPassword}
            onChange={(e) => setNewPassword(e.target.value)}
            autoComplete="new-password"
            className="mt-1 w-full rounded-xl border border-slate-800 bg-slate-950/80 px-3 py-2.5 text-sm text-slate-100 outline-none focus:border-violet-500/50"
          />
        </div>
        <div>
          <label className="text-[11px] text-slate-500">{t('crm.account.security.confirm')}</label>
          <input
            type="password"
            value={newPassword2}
            onChange={(e) => setNewPassword2(e.target.value)}
            autoComplete="new-password"
            className="mt-1 w-full rounded-xl border border-slate-800 bg-slate-950/80 px-3 py-2.5 text-sm text-slate-100 outline-none focus:border-violet-500/50"
          />
        </div>
      </div>

      <button
        type="button"
        onClick={() => void handleChangePassword()}
        disabled={passSaving}
        className="rounded-xl border border-slate-600 bg-slate-100 px-4 py-2.5 text-sm font-semibold text-slate-900 hover:bg-white disabled:opacity-50"
      >
        {passSaving ? t('crm.account.security.saving') : t('crm.account.security.save')}
      </button>
    </div>
  );
};

import React from 'react';
import { useTranslation } from 'react-i18next';
import { setAppLanguage } from '../../../i18n';

export const AccountPreferencesTab: React.FC = () => {
  const { t, i18n } = useTranslation();
  const lang = (i18n.language || 'ru').slice(0, 2);

  return (
    <div className="max-w-xl space-y-6">
      <div>
        <h2 className="text-lg font-semibold text-slate-50">{t('crm.account.preferences.title')}</h2>
        <p className="mt-1 text-sm text-slate-400">{t('crm.account.preferences.subtitle')}</p>
      </div>

      <div>
        <label className="text-[11px] text-slate-500">{t('crm.account.preferences.language')}</label>
        <select
          value={lang === 'en' ? 'en' : lang === 'tr' ? 'tr' : 'ru'}
          onChange={(e) => setAppLanguage(e.target.value as 'ru' | 'en' | 'tr')}
          className="mt-2 w-full max-w-xs rounded-xl border border-slate-800 bg-slate-950/80 px-3 py-2.5 text-sm text-slate-100 outline-none focus:border-violet-500/50"
        >
          <option value="ru">Русский</option>
          <option value="en">English</option>
          <option value="tr">Türkçe</option>
